        var replyTo = GrainId.Create("reply", Guid.NewGuid().ToString());
        var data = CreateEnvelopeData("test-body");
        var createdAt = DateTimeOffset.UtcNow;

        var original = new DurableEnvelope
        {
            MessageId = messageId,
            SenderId = senderId,
            ReceiverId = receiverId,
            RouteKey = routeKey,
